"""Q6 round 2: patch/add Q6 entries in /output/report.json (idempotent; run AFTER s157). python3 -I s164_update_report_q6r2.py"""
import json
p='/output/report.json'; d=json.load(open(p)); R=d['results']
R[:]=[x for x in R if not x['quantity'].startswith('Q6r2:')]
d['recipe']=[x for x in d['recipe'] if not x['description'].startswith('Q6r2:')]
d['caveats']=[x for x in d['caveats'] if not x.startswith('Q6r2:')]
A=lambda n,v:{'name':n,'value':v}
t=json.load(open('/workspace/out/q6r2/s160.json')); f=json.load(open('/workspace/out/q6r2/s163.json')); s162=json.load(open('/workspace/out/q6r2/s162.json'))
# --- table of T_b(scale)
rows=[]
for ln in t:
    for rn in ('N','S','Bridge','E1','E2'):
        r=t[ln][rn]; k=list(r)
        rows.append('%s %s: %.2f / %.2f / %.2f / %.2f (Xb4d-beam %.2f, Xb4d native %.2f); slope %.2f'%(ln.replace('3-2',''),rn,r['native 0.24"']['Tb'],r['55pc(0.28")']['Tb'],r['120pc(0.62")']['Tb'],r['250pc(1.29")']['Tb'],r['Xb4d beam 0.93x0.74"']['Tb'],r['Xb4d native']['Tb'],f['tb'][ln][rn]['slope_native_to_250pc']))
common=[A('distance','40 Mpc, 1" = 194 pc (Sakamoto+2014 35 Mpc, 170 pc/": pc values x0.88)'),A('smoothing','Xb4b pbcor cube -> T_b(RJ) map per channel (native beam 0.246x0.232", PA -49) -> convolution with a unit-area elliptical Gaussian kernel whose covariance is (target beam - native beam) -> beam-averaged T_b at the new resolution (flux conserving); circular targets 55/120/250 pc = 0.28/0.62/1.29" and the Xb4d beam 0.93x0.74" PA -86; peak = 3-channel boxcar maximum at the pixel of maximum smoothed moment-0 within 0.4" of the nominal position, line-free median subtracted; no uv-plane filtering is modelled: Xb4b lacks scales >~2-3"'),
 A('peak definition','native-resolution peak-pixel value of the 3-channel boxcar spectrum (HCN N 2.65 K here vs 2.46 K in the earlier s151 table: different peak-pixel choice, +-8%)')]
R.append({'quantity':'Q6r2: peak T_b of HCO+ and HCN 3-2 versus beam size, 55-250 pc (dilution relation and test of a smooth medium)',
 'target':'N, S, Bridge, E1, E2; HCO+ 3-2 and HCN 3-2',
 'value':('Peak T_b(RJ) [K] at native 0.24" (49 pc) / 55 pc / 120 pc / 250 pc [Xb4d-beam 0.93x0.74"; Xb4d native], statistical error 0.01-0.09 K: '+'; '.join(rows)+'. '
  'Result: in every region and both lines the peak T_b falls by a factor 3.3-7.6 (HCO+: N 4.0, S 5.7, Bridge 3.3, E1 3.9, E2 7.6; HCN: N 5.3, S 6.2, Bridge 4.0, E1 5.8, E2 6.2) from 49 to 250 pc, i.e. T_b ~ theta^-0.7..-1.2 (an unresolved point source would give -2, a smooth medium 0). The 3.4x drop at S from 0.25" to 1" found by the reviewer is reproduced (0.85 K at the Xb4d beam from 2.8 K). '
  'Validation: Xb4b smoothed to the Xb4d beam agrees with the independently imaged native Xb4d to 0-15% (ratio Xb4d/smoothed 1.00-1.15 for 9 of 10 cases, i.e. a modest <=15% loss of extended flux in Xb4b; 0.81 for the faint HCN S). '
  'Interpretation: the dense gas at 50 pc is NOT a smooth medium of constant brightness (cf. Brunetti+2021: no trend of surface density, T_b and sigma between 55 and 120 pc in CO 2-1, i.e. smooth gas down to 55 pc): between 55 and 120 pc our T_b already drops by 1.5-2.6x (HCO+ N 2.3->1.1, S 2.5->1.2, E2 1.7->0.64 K) and the 3-2 dense-gas tracers are concentrated in cores of ~0.35-0.55" (70-110 pc) on a fainter (0.3-0.9 K RJ) 1.5-2" pedestal. '
  'Beam-core model T_b(theta)=Tc d^2/(d^2+theta^2)+Tp w^2/(w^2+theta^2) (w=1.8" pedestal fixed, 5 beams incl. Xb4d-beam, errors max(stat,3%)): well-constrained only for S HCO+ (d=0.35", Tc 3.5 K, Tp 0.37 K, chi2 0.2/2 dof: filling of the core in the 0.24" beam 0.68, i.e. the beam-averaged 2.8 K RJ is only 20% below the core-resolved brightness) and the HCN Bridge/E1/E2/S fits (d 0.34-0.55", Tc 0.9-1.4 K, filling in the 0.24" beam 0.65-0.8); N is degenerate (HCO+ d 0.11", Tc 11 K; HCN d 0.26", Tc 3.7 K, chi2 10): the core+Gaussian-pedestal form does not describe N (plateau in the radial profile), so for N only the lower limit Tc>=2.8 K (HCO+) / 2.65 K (HCN) and the empirical slope -0.8..-1.0 are quoted. '
  'Consequence for beam filling: (i) the sentence "dilution is only 1.2-1.35" holds only for the core within the 0.24" beam, i.e. the filling of the ~100 pc core is ~0.7-0.8; (ii) the T_b at 250 pc is only 0.13-0.3 of that at 49 pc, i.e. the beam-averaged brightness of the dense gas at 250 pc corresponds to a filling of 0.13-0.3 relative to the 50 pc cores; (iii) the 0.24->0.28" step already lowers T_b by 5-20% and no flattening is seen at the finest scale, so filling at <50 pc cannot be assessed from these data, the 5-7 K Planck-equivalent T_b is a lower limit on T_ex for any f<1 and f<1 at 50 pc remains allowed down to the RADEX lower limits of the earlier entry (0.02-0.1).'),
 'uncertainty':'statistical per point 0.01-0.09 K (<=10%); calibration 5%; peak-position choice +-8% (HCN N); missing extended flux in Xb4b lowers the 120/250 pc points by <=15% (Xb4d/smoothed ratio) so the true slope is shallower by ~0.1; Tc/d of the core model: S HCO+ +-30%, N unconstrained',
 'unit':'K (RJ)','assumptions':common,'confidence':'medium','evidence':'scripts/s160_q6r2_tb_scale.py (out/q6r2/s160.json), s163_q6r2_fit_virial.py (fits, out/q6r2/s163.json, out/q6r2/tb_vs_scale.png)'})
# --- size robustness + imaging cross-check
cr=lambda ln,rn,v,k: s162['lines'][ln][rn][v][k] if v in s162['lines'][ln][rn] else float('nan')
R.append({'quantity':'Q6r2: robustness of the 0.24" dense-gas sizes: radial-profile half-power diameters, beam-convolved core+pedestal fits, and manual-cube cross-check',
 'target':'HCO+ 3-2 and HCN 3-2 at N, S, Bridge, E1, E2',
 'value':('(a) Azimuthally averaged radial profile about the peak, FWHM = 2 x radius where the mean profile drops to half of its peak, deconvolved sqrt(D^2-bmaj*bmin) [arcsec, regular cube vs half-max-area of the previous entry]: HCO+ N 0.40 (0.52), S 0.48 (0.50), Bridge 0.54 (0.83), E1 0.60 (0.69), E2 0.38 (0.60); HCN N 0.40 (0.41), S 0.37 (0.43), Bridge 0.51 (0.69), E1 0.16 (0.55, S/N 6), E2 0.31 (0.48). Radial sizes are 0.0-0.1" smaller for compact nuclei and up to 0.3" smaller for the elongated Bridge/E2 (the area criterion picks up elongation); the S HCO+ and N HCN agree to 0.02-0.04". '
  '(b) Beam-convolved 2D fit core (elliptical Gaussian, free orientation, intrinsic size) + circular pedestal of fixed intrinsic FWHM 1.2/1.8/2.5" (the 2-Gaussian fit with free pedestal width was unconstrained), 9 free parameters, core intrinsic geometric-mean FWHM: HCO+ S 0.33/0.54/0.54", core share of the model flux 17/28/21%; HCN S 0.53/0.49/0.48" (core share 53/38/27%); HCO+ E2 0.60/0.57/0.59"; HCO+ E1 0.67/0.72/0.72" (no pedestal needed); HCN E1 0.43/0.46/0.50"; HCN E2 0.28/0.40/0.48"; N is NOT constrained (HCO+ 0.05/0.34/1.2", HCN 0.07/0.47/0.81": profile has a plateau at r=0.4-0.6" at 40% of the peak (HCO+) which a core+Gaussian pedestal cannot reproduce; per-beam chi2 of 300-700 shows the residual structure is real). Core FWHM for S (pedestal 1.8-2.5") 0.54+-0.02 (stat) x/- 0.2 (pedestal-width systematic incl. 1.2") vs 0.50 from half-max: the half-max size is not biased by the pedestal at S at the 0.05" level, and the core-pedestal flux split is ~20-30% core / 70-80% pedestal within 2.5" for HCO+ S (as the 16-31% r<0.5" aperture fractions). '
  '(c) Imaging cross-check with the independently imaged manual 26.6 MHz HCO+ cube (beam 0.222x0.201" PA -26"; E1, E2 outside its field): half-max-area deconvolved D regular/manual: N 0.52/0.36, S 0.50/0.46, Bridge 0.83/0.82; radial D: N 0.40/0.34, S 0.48/0.43, Bridge 0.54/0.55. Peak surface brightness in K km/s (peak moment-0 per beam area) agrees within 3-6% (N 21.8 vs 22.4, S 17.9 vs 19.0 Jy km/s per arcsec2 of beam) i.e. T_b does not rise when the beam shrinks 0.24->0.21". The half-max N size differs by 0.16" (>0.05" threshold: flagged systematic: the N half-max contour lies on the pedestal and depends on weighting), S by 0.04", Bridge by 0.01". '
  'Adopted: HCO+ S 0.50 +-0.05" (97+-10 pc), HCN S 0.43+-0.06 (83+-12 pc), HCN N 0.40 +-0.05 (78 pc); HCO+ N 0.45 +-0.1" (87 +-20 pc: half-max 0.52, radial 0.40/0.34, manual half-max 0.36), Bridge 0.55-0.8", E1/E2 0.4-0.7". Sizes of the compact components are therefore 1.4-2 beams (70-100 pc) for the nuclei: resolved but not by large factors, and the earlier "~100 pc" for N is an upper end.'),
 'uncertainty':'S: +-0.05"; N: +0.07/-0.15" (imaging/weighting dependent); Bridge, E1, E2 +-0.15" (blending, elongation, S/N); pedestal-width systematic of the core fit up to +-0.2" at S for the extreme 1.2" pedestal',
 'unit':'arcsec (pc at 194 pc/")','assumptions':common+[A('radial profile','mean in 1-pixel annuli about the peak of the 3-px-smoothed moment-0 (|v-2780|<350 km/s), centre = peak within 0.4" of nominal'),A('core fit','intrinsic Gaussian convolved analytically with the elliptical beam (covariance addition); pedestal centre free within 0.6", core centre within 0.3"; statistical error from 40 correlated-noise refits (0.01-0.03" for S, N not meaningful)')],
 'confidence':'medium','evidence':'scripts/s161_q6r2_core_pedestal.py (out/q6r2/s161.json), s162_q6r2_profile_manual_cont.py (out/q6r2/s162.json)'})
# --- virial
V=f['vir']; g=lambda ln,rn,k: V[ln][rn][k]
vt='; '.join('%s %s A %.1e / B %.1e / C %.1e / C2 %.1e / D %.1e / A@35Mpc %.1e'%(ln.replace('3-2',''),rn,g(ln,rn,'A'),g(ln,rn,'B'),g(ln,rn,'C'),g(ln,rn,'C2'),g(ln,rn,'Dv'),g(ln,rn,'A35')) for ln in V for rn in V[ln])
R.append({'quantity':'Q6r2: virial-style masses of the 0.24" dense-gas structures with explicit radius and sigma conventions (upper limits)',
 'target':'HCO+ and HCN 3-2, N, S, Bridge, E1, E2','value':('M_vir=1040 sigma^2 R [Msun, sigma km/s, R pc] (Rosolowsky & Leroy 2006 form, as used for the CO catalogue of Brunetti+2022). Variants: A = R=1.91*sigma_r with sigma_r = D_dec(half-max)/2.355 and sigma = FWHM(1 Gaussian, or half-max if the profile is non-Gaussian)/2.355 [earlier convention]; B = R = D_half-max/2 (half-max radius; 0.6x A); C = sigma from the peak-pixel second moment (noise-robust, contiguous channels >2 sigma) instead of the Gaussian FWHM; C2 = C with the velocity-gradient smearing and channel width removed in quadrature; D = A with the radial-profile D_dec; A@35 = A with 1"=170 pc (x0.88). '
  +vt+'. Result: the nuclei span 0.9-3.0e8 Msun and the clumps E1/E2 3-8e7 Msun over all variants (factor 1.6-2.2 spread inside each object); the CO catalogue median M_vir 5.4e7 (Brunetti+2022, alpha_vir 4.3) is reproduced by E1/E2 (HCO+ 3.2-7.3e7, 3.3-7.1e7 in the variants; HCN 2.3-7.8e7) and exceeded by factors 2-5 by the nuclei and the Bridge. So the statement "E1/E2 are CO-cloud-like and the nuclei are 2-3x broader" survives all conventions; the claimed agreement of the clumps is good to a factor 2 only. All are upper limits for a bound mass (non-gravitational sigma: rotation, streaming and outflow in the nuclei; the sigma of N is non-Gaussian, 47 (1G) vs 58 (mom2) km/s). Not a dynamical-mass measurement.'),
 'uncertainty':'factor ~2 from conventions (R definition 0.6x, sigma_mom2 vs FWHM up to 1.5x), distance 0.88x','unit':'Msun','assumptions':common,'confidence':'low','evidence':'scripts/s163_q6r2_fit_virial.py (out/q6r2/s163.json)'})
# --- patch earlier entries
for x in R:
    if x['quantity'].startswith('Q6: peak brightness temperatures at 0.24"'):
        a=x['value'].index('Beam dilution:'); b=x['value'].index('Filling implied by')
        x['value']=x['value'][:a]+('Beam dilution (revised, see Q6r2 T_b vs scale): a Gaussian source of the measured half-max size within the 0.24" beam is diluted by only 1.2-1.35 (core filling ~0.7-0.8), but the measured T_b falls 3-8x between 49 and 250 pc (slope -0.7..-1.2), so the 1.2-1.35 describes the ~100 pc core only; the pedestal and sub-beam clumpiness is what the T_b(scale) relation measures, and T_b is still rising at the finest scale. ')+x['value'][b:]
        x['value']=x['value'].replace('and filling and excitation cannot be separated with one line pair','and filling and excitation cannot be separated with one line pair (the T_b(scale) trend gives the scale dependence of filling but not the excitation)')
    if x['quantity'].startswith('Q6: 257.8 GHz continuum brightness'):
        c=s162['cont']
        x['value']=('Native (unsmoothed) peak pixel of the Xb4b 4-spw continuum map (beam 0.245x0.235", rms %.3f mJy/beam, measured at r=8-14"): S %.2f mJy/beam (T_b(RJ) %.2f K), N %.2f (%.2f K), SE %.2f (%.2f K), E1 %.2f (%.2f K), E2 %.2f (%.2f K), Bridge %.2f (%.2f K). The earlier 1.64 mJy/beam (0.53 K) was the 3-px-smoothed peak and 10%% low; the half-max sizes use the smoothed map (the 10%% level shift moves the S size by <0.02"). '%(c['rms_mJy'],c['S']['peak_native_mJy'],c['S']['Tb_RJ'],c['N']['peak_native_mJy'],c['N']['Tb_RJ'],c['SE']['peak_native_mJy'],c['SE']['Tb_RJ'],c['E1']['peak_native_mJy'],c['E1']['Tb_RJ'],c['E2']['peak_native_mJy'],c['E2']['Tb_RJ'],c['Bridge']['peak_native_mJy'],c['Bridge']['Tb_RJ'])
         +'If ALL of the continuum is dust (free-free ignored: upper bound) with Td=50 (100) K: tau %.4f (%.4f) and beam-averaged gas Sigma %.1e (%.1e) Msun/pc2 at S, %.1e (%.1e) at N, %.1e (%.1e) at SE, with kappa_gas=0.1 (nu/1 THz)^1.5 cm2/g(gas) (factor >=3 uncertain): comparable to the CO-based peak surface densities (3-6e3, Sakamoto+2014; up to 5.5e3 at 55 pc, Brunetti+2021). The S continuum is optically thin and 4.8x fainter in T_b (RJ) than the HCO+ 3-2 peak (2.81 K; HCN 1.18 K: ratio 2.0), so continuum absorption of the lines does not occur.'%(c['S']['tau_Td50'],c['S']['tau_Td100'],c['S']['Sigma_Td50'],c['S']['Sigma_Td100'],c['N']['Sigma_Td50'],c['N']['Sigma_Td100'],c['SE']['Sigma_Td50'],c['SE']['Sigma_Td100']))
        x['evidence']='scripts/s162_q6r2_profile_manual_cont.py (native peaks, out/q6r2/s162.json); previous s155'
        x['assumptions']=[a for a in x['assumptions'] if a['name']!='dust']+[A('dust','kappa_gas=0.1 (nu/1000 GHz)^1.5 cm2/g gas; Td 50-100 K; no free-free subtraction (upper bound)')]
    if x['quantity'].startswith('Q6: line widths'):
        x['value']+=' [Round 2: the virial masses above use R_eff=1.91 sigma_r with half-max D; the variants with other R/sigma/distance conventions (0.6-1.5x) are in the entry "Q6r2: virial-style masses"; the CO comparison holds only to a factor 2.]'
d['recipe'].append({'description':'Q6r2: T_b(scale) by smoothing Xb4b cubes (s160), core+pedestal beam-convolved fits (s161), radial-profile sizes, manual-cube cross-check, native continuum peaks (s162), power-law/core fits and virial variants (s163), report patch (s164)',
 'scripts':[f'/workspace/scripts/{x}' for x in ('s160_q6r2_tb_scale.py','s161_q6r2_core_pedestal.py','s162_q6r2_profile_manual_cont.py','s163_q6r2_fit_virial.py','s164_update_report_q6r2.py')],'order':27,'stage':'modelling'})
d['caveats'].append('Q6r2: peak T_b of the dense gas falls 3-8x between 49 and 250 pc (slope -0.7..-1.2), so beam filling at 50 pc cannot be taken from a single Gaussian-dilution factor and the gas is not a smooth medium; N has no well-defined core+pedestal decomposition and its size is imaging dependent (half-max 0.52" regular vs 0.36" manual cube); virial masses depend by a factor ~2 on the R/sigma convention and are upper limits.')
json.dump(d,open(p,'w'),indent=1)
